function normalize(s) {
  return (s || '')
    .toString()
    .toLowerCase()
    .replace(/[\u064B-\u0652\u0670\u0640]/g, '')
    .replace(/[إأآا]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/[ىي]/g, 'ي')
    .replace(/ؤ/g, 'و')
    .replace(/ئ/g, 'ي')
    .replace(/\s+/g, ' ')
    .trim();
}

const CORE_STEMS = [
  'كلب','حمار','بهيمه','بهايم','تافه','غبي','احمق','حمقاء',
  'منحط','حقير','قذر','وسخ','نذل',
  'قحبه','قحاب','عاهره','شرموطه','شرموط','منيوك','منايك',
  'زامل','زواميل','مخنث','لوطي',
  'كس','زب','زبر','ايري','ايره','طيز','طياز','حلقي'
];

const PHRASES_RAW = [
  'ابن الحرام','بنت الحرام','ولد الحرام',
  'ابن كلب','بنت كلب','ابن الكلب','بنت الكلب','ولد كلب',
  'ابن حرام','بنت حرام','ولد حرام',
  'ابن قحبه','بنت قحبه','ولد قحبه','ابن القحبه','بنت القحبه',
  'ابن عاهره','بنت عاهره','ابن العاهره','بنت العاهره',
  'يلعن ابوك','يلعن ابوها','يلعن ابوي','يلعن امك','يلعن امها','يلعن الي خلفوك',
  'كس امك','كس امه','كس امها','كس اختك','كس اخته','كس ابوك',
  'بط ايري','بط ايره','منيك امك','نياك امك','نياك اختك'
];

const PREFIXES = ['','ال'];
const SUFFIXES = ['','ك','ه','ها','هم','كم','نا','هن','كن','ي','ين','ات'];

function expand(stem) {
  const out = new Set();
  const n = normalize(stem);
  for (const p of PREFIXES) for (const s of SUFFIXES) out.add(p + n + s);
  return out;
}

const TOKEN_SET = new Set();
for (const stem of CORE_STEMS) for (const v of expand(stem)) TOKEN_SET.add(v);

const PHRASES = [...new Set(PHRASES_RAW.map(normalize))];

const extra = ($env.BANNED_WORDS || '').split(',').map(w => normalize(w.trim())).filter(Boolean);
for (const w of extra) {
  if (w.includes(' ')) PHRASES.push(w);
  else TOKEN_SET.add(w);
}

const body = $input.first().json.body;
const raw = body.content || '';
const norm = normalize(raw);
const tokens = norm.split(/[^\u0600-\u06FF\u0750-\u077Fa-z0-9]+/u).filter(Boolean);

const found = [];
for (const t of tokens) if (TOKEN_SET.has(t)) found.push(t);
for (const p of PHRASES) if (p && norm.includes(p)) found.push(p);

return [{ json: { ...body, bannedWordsFound: [...new Set(found)], isViolation: found.length > 0 } }];

